"""Hidden behavioral tests for cmark: render_latex. Generated by pbkit from the gold binary."""


def test_kitchen_sink_latex(run):
    r = run(args=['-t', 'latex'], stdin=b'# Heading *one*\n\nSetext heading\n--------------\n\nA paragraph with *emph*, **strong**, ***both***, `code`, a [link](http://example.com "Title"),\nan ![image](img.png "Img"), <http://auto.link>, <me@example.com>, a hard\\\nbreak and a soft\nbreak. Entities: &copy; &#x27; &#39; &nbsp;. Backslash \\* escapes.\n\n> A block quote\n> with *two* lines\n>\n> > nested quote\n\n1. first\n2. second\n   - nested bullet\n   - another\n\n     with a paragraph\n3. third\n\n- [ ] not a task list\n* different bullet\n\n```python\ndef f(x):\n    return x * 2\n```\n\n    indented code block\n\n<div class="raw">\n*not emph*\n</div>\n\nInline <span>html</span> and <!-- comment -->.\n\n***\n\n[ref link][ref] and [collapsed][] and [shortcut].\n\n[ref]: /url "ref title"\n[collapsed]: </with spaces>\n[shortcut]: http://x.y \'single\'\n')
    assert r.stdout == b'\\section{Heading \\emph{one}}\n\n\\subsection{Setext heading}\n\nA paragraph with \\emph{emph}, \\textbf{strong}, \\emph{\\textbf{both}}, \\texttt{code}, a \\href{http://example.com}{link},\nan \\protect\\includegraphics{img.png}, \\url{http://auto.link}, \\href{mailto:me@example.com}{\\nolinkurl{me@example.com}}, a hard\\\\\nbreak and a soft\nbreak. Entities: \xc2\xa9 \\textquotesingle{} \\textquotesingle{} ~. Backslash * escapes.\n\n\\begin{quote}\nA block quote\nwith \\emph{two} lines\n\n\\begin{quote}\nnested quote\n\n\\end{quote}\n\n\\end{quote}\n\n\\begin{enumerate}\n\\item first\n\n\\item second\n\n\\begin{itemize}\n\\item nested bullet\n\n\\item another\n\nwith a paragraph\n\n\\end{itemize}\n\n\\item third\n\n\\end{enumerate}\n\n\\begin{itemize}\n\\item {[} {]} not a task list\n\n\\end{itemize}\n\n\\begin{itemize}\n\\item different bullet\n\n\\end{itemize}\n\n\\begin{verbatim}\ndef f(x):\n    return x * 2\n\\end{verbatim}\n\n\\begin{verbatim}\nindented code block\n\\end{verbatim}\n\nInline html and .\n\n\\begin{center}\\rule{0.5\\linewidth}{\\linethickness}\\end{center}\n\n{ref link} and {collapsed} and \\href{http://x.y}{shortcut}.\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_lists_latex(run):
    r = run(args=['-t', 'latex'], stdin=b'- a\n- b\n\n- c\n\n1) x\n2) y\n\n10. ten\n11. eleven\n\n* loose\n\n  para\n* tight\n')
    assert r.stdout == b'\\begin{itemize}\n\\item a\n\n\\item b\n\n\\item c\n\n\\end{itemize}\n\n\\begin{enumerate}\n\\item x\n\n\\item y\n\n\\end{enumerate}\n\n\\begin{enumerate}\n\\setcounter{enumi}{9}\n\\item ten\n\n\\item eleven\n\n\\end{enumerate}\n\n\\begin{itemize}\n\\item loose\n\npara\n\n\\item tight\n\n\\end{itemize}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_quotes_and_dashes_latex(run):
    r = run(args=['-t', 'latex'], stdin=b'"Hello," said the spider. \'Shelob\' is my name -- or --- maybe... it\'s 1990\'s.\n')
    assert r.stdout == b'\\textquotedbl{}Hello,\\textquotedbl{} said the spider. \\textquotesingle{}Shelob\\textquotesingle{} is my name -{}- or -{}-{}- maybe... it\\textquotesingle{}s 1990\\textquotesingle{}s.\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_special_chars_latex(run):
    r = run(args=['-t', 'latex'], stdin=b'Special: \\ { } $ & # ^ _ % ~ < > " \' | and . at line start\n\n.SH not a macro\n\'quote\n')
    assert r.stdout == b'Special: \\textbackslash{} \\{ \\} \\$ \\& \\# \\^{} \\_ \\% \\textasciitilde{} \\textless{} \\textgreater{} \\textquotedbl{} \\textquotesingle{} \\textbar{} and . at line start\n\n.SH not a macro\n\\textquotesingle{}quote\n'
    assert r.stderr == b''
    assert r.returncode == 0


