def test_links_and_urls_latex(run):
    r = run(args=['-t', 'latex'], stdin=b'[a](<b c>) [d](e(f)g) [h](i\\)j) [k](l "m" ) [n](javascript:alert(1)) [o](data:image/png;base64,x) [p](vbscript:x) [q](file:///etc) ![r](data:text/html;x) <javascript:y>\n')
    assert r.stdout == b'{a} {d} {h} {k} \\href{javascript:alert(1)}{n} \\href{data:image/png;base64,x}{o} \\href{vbscript:x}{p} \\href{file:///etc}{q} \\protect\\includegraphics{data:text/html;x} \\url{javascript:y}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_raw_html_latex(run):
    r = run(args=['-t', 'latex'], stdin=b'<script>alert(1)</script>\n\n<p onclick="x">p</p>\n\nInline <b onmouseover=x>b</b> <?php ?> <!DOCTYPE x> <![CDATA[ y ]]>\n')
    assert r.stdout == b'Inline b   \n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_headings_latex(run):
    r = run(args=['-t', 'latex'], stdin=b'# h1\n## h2 ##\n### h3 #\n#### h4\n##### h5\n###### h6\n####### not\n\nH\n=\n\nH2\n---\n')
    assert r.stdout == b'\\section{h1}\n\n\\subsection{h2}\n\n\\subsubsection{h3}\n\n\\paragraph{h4}\n\n\\subparagraph{h5}\n\n{h6}\n\n\\#\\#\\#\\#\\#\\#\\# not\n\n\\section{H}\n\n\\subsection{H2}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_code_latex(run):
    r = run(args=['-t', 'latex'], stdin=b'``` js {.class}\nconsole.log(`x`);\n```\n\n~~~~\n~~~\n~~~~\n\n`` a`b ``\n\n````\n```\n````\n')
    assert r.stdout == b'\\begin{verbatim}\nconsole.log(`x`);\n\\end{verbatim}\n\n\\begin{verbatim}\n~~~\n\\end{verbatim}\n\n\\texttt{a`b}\n\n\\begin{verbatim}\n```\n\\end{verbatim}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_breaks_latex(run):
    r = run(args=['-t', 'latex'], stdin=b'line one\nline two  \nline three\\\nline four\n')
    assert r.stdout == b'line one\nline two\\\\\nline three\\\\\nline four\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_unicode_latex(run):
    r = run(args=['-t', 'latex'], stdin=b'\xc3\x9cn\xc3\xafc\xc3\xb6d\xc3\xa9 \xe2\x80\x94 \xe2\x80\x9cquotes\xe2\x80\x9d \xe2\x80\x98single\xe2\x80\x99 \xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e *\xe5\xbc\xb7\xe8\xaa\xbf* \xf0\x9f\x98\x80 \xc2\xa0nbsp\n')
    assert r.stdout == b"\xc3\x9cn\xc3\xafc\xc3\xb6d\xc3\xa9 --- ``quotes'' `single' \xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e \\emph{\xe5\xbc\xb7\xe8\xaa\xbf} \xf0\x9f\x98\x80 ~nbsp\n"
    assert r.stderr == b''
    assert r.returncode == 0


def test_tables_not_supported_latex(run):
    r = run(args=['-t', 'latex'], stdin=b'| a | b |\n|---|---|\n| 1 | 2 |\n')
    assert r.stdout == b'\\textbar{} a \\textbar{} b \\textbar{}\n\\textbar{}-{}-{}-\\textbar{}-{}-{}-\\textbar{}\n\\textbar{} 1 \\textbar{} 2 \\textbar{}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_nested_structure_latex(run):
    r = run(args=['-t', 'latex'], stdin=b'> 1. > - a\n>    >   b\n> 2. c\n>\n>        code in list\n')
    assert r.stdout == b'\\begin{quote}\n\\begin{enumerate}\n\\item \\begin{quote}\n\\begin{itemize}\n\\item a\nb\n\n\\end{itemize}\n\n\\end{quote}\n\n\\item c\n\n\\begin{verbatim}\ncode in list\n\\end{verbatim}\n\n\\end{enumerate}\n\n\\end{quote}\n'
    assert r.stderr == b''
    assert r.returncode == 0
